import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#world');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9caeaa); scene.fog=new THREE.FogExp2(0x9caeaa,.009);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,350);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'}); renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
scene.add(new THREE.HemisphereLight(0xdce9e9,0x35402f,2.1));const sun=new THREE.DirectionalLight(0xffe6bf,3.2);sun.position.set(-35,55,18);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const mats={ground:new THREE.MeshStandardMaterial({color:0x687d50,roughness:1}),grass:new THREE.MeshStandardMaterial({color:0x80905a,roughness:1}),trunk:new THREE.MeshStandardMaterial({color:0x554435,roughness:1}),leaves:new THREE.MeshStandardMaterial({color:0x354e3d,roughness:.92}),leaf2:new THREE.MeshStandardMaterial({color:0x536846,roughness:1}),stone:new THREE.MeshStandardMaterial({color:0x797b69,roughness:1}),darkStone:new THREE.MeshStandardMaterial({color:0x41483d,roughness:1}),gold:new THREE.MeshStandardMaterial({color:0xd9b96e,metalness:.45,roughness:.35}),red:new THREE.MeshStandardMaterial({color:0x691e26,roughness:.62}),cloak:new THREE.MeshStandardMaterial({color:0x171b1b,roughness:.75}),skin:new THREE.MeshStandardMaterial({color:0xe1b999,roughness:.8}),armor:new THREE.MeshStandardMaterial({color:0x373a38,metalness:.58,roughness:.4}),silver:new THREE.MeshStandardMaterial({color:0xb8c3b9,metalness:.78,roughness:.22}),wolf:new THREE.MeshStandardMaterial({color:0x6f7565,roughness:.9}),enemy:new THREE.MeshStandardMaterial({color:0x57443f,roughness:1}),fire:new THREE.MeshStandardMaterial({color:0xff9b54,emissive:0xd54418,emissiveIntensity:2})};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(260,260,1,1),mats.ground);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);
const rand=(a,b)=>a+Math.random()*(b-a);const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function mesh(geo,mat,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function makeTree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);mesh(new THREE.CylinderGeometry(.18,.32,2.7,7),mats.trunk,g,0,1.35,0);for(let i=0;i<3;i++){const c=mesh(new THREE.ConeGeometry(1.38-i*.21,2.3,8),i===1?mats.leaf2:mats.leaves,g,0,2.9+i*.9,0);c.rotation.y=rand(0,6)}return g}
function makeRock(x,z,s=1){const r=mesh(new THREE.DodecahedronGeometry(s,0),mats.stone,scene,x,s*.42,z);r.scale.set(1,.7,.85);r.rotation.set(rand(0,1),rand(0,4),rand(0,1));return r}
// Wild meadow, ringed by a dense forest; the central road leads to the distant kingdom.
for(let i=0;i<220;i++){const x=rand(-112,112),z=rand(-110,110);if(Math.abs(x)<17&&z>-32&&z<34)continue;if(Math.abs(x-z*.32)<5&&z<24)continue;makeTree(x,z,rand(.72,1.42))}
for(let i=0;i<55;i++){let x=rand(-23,23),z=rand(-27,27);if(Math.hypot(x,z)<5)continue;makeRock(x,z,rand(.3,.9))}
// Grass tufts and flowers add texture across the playable clearing.
const tuftGeo=new THREE.ConeGeometry(.055,.34,4);for(let i=0;i<900;i++){let x=rand(-48,48),z=rand(-48,48);if(Math.abs(x)<2&&Math.abs(z)<3)continue;let t=mesh(tuftGeo,Math.random()>.5?mats.grass:mats.leaf2,scene,x,.14,z);t.rotation.z=rand(-.3,.3);t.rotation.y=rand(0,6)}
// A pale stone path curves from the starting clearing toward the castle.
const pathMat=new THREE.MeshStandardMaterial({color:0x9a927a,roughness:1});for(let i=0;i<36;i++){let z=25-i*2.35,x=Math.sin(i*.115)*5;let p=mesh(new THREE.BoxGeometry(3.2+rand(-.6,.6),.12,2+rand(-.4,.4)),pathMat,scene,x,.08,z);p.rotation.y=rand(-.12,.12)}
function makeBuilding(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(s);scene.add(g);mesh(new THREE.BoxGeometry(9,5,7),mats.stone,g,0,2.5,0);mesh(new THREE.ConeGeometry(6.7,4.8,4),mats.red,g,0,7,0).rotation.y=Math.PI/4;mesh(new THREE.BoxGeometry(1.4,2.6,.25),mats.darkStone,g,0,1.35,3.61);for(const xx of [-2.7,2.7]){mesh(new THREE.BoxGeometry(.8,2,.15),mats.gold,g,xx,3.7,3.55)}return g}
makeBuilding(-13,-25,.8);makeBuilding(20,-32,.62);
// Distant castle silhouette
const castle=new THREE.Group();castle.position.set(-5,0,-94);scene.add(castle);mesh(new THREE.BoxGeometry(30,18,18),mats.stone,castle,0,9,0);for(let i=-1;i<=1;i++){mesh(new THREE.BoxGeometry(8,27,8),mats.stone,castle,i*11,13,0);let t=mesh(new THREE.ConeGeometry(6,15,4),mats.red,castle,i*11,34,0);t.rotation.y=Math.PI/4}mesh(new THREE.BoxGeometry(18,30,7),mats.stone,castle,0,15,-9);mesh(new THREE.ConeGeometry(10,19,4),mats.darkStone,castle,0,39,-9).rotation.y=Math.PI/4;
// campfire
const fireGroup=new THREE.Group();fireGroup.position.set(1,0,1);scene.add(fireGroup);for(let i=0;i<9;i++){let a=i*Math.PI*2/9;mesh(new THREE.CylinderGeometry(.13,.17,1.15,7),mats.trunk,fireGroup,Math.cos(a)*.55,.18,Math.sin(a)*.55).rotation.z=Math.PI/2;}
mesh(new THREE.IcosahedronGeometry(.45,1),mats.fire,fireGroup,0,.72,0);let flameLight=new THREE.PointLight(0xff873a,3,10);flameLight.position.y=1.2;fireGroup.add(flameLight);
function person({coat=mats.cloak,hood=true,accent=mats.red}={}){const g=new THREE.Group();const body=mesh(new THREE.CylinderGeometry(.3,.48,1.55,8),coat,g,0,1.22,0);body.rotation.z=-.05;mesh(new THREE.SphereGeometry(.31,12,10),mats.skin,g,0,2.2,0);if(hood){const h=mesh(new THREE.SphereGeometry(.39,10,8,0,Math.PI*2,0,Math.PI*.72),coat,g,0,2.34,-.03);h.scale.z=.95;mesh(new THREE.SphereGeometry(.34,10,8,0,Math.PI*2,0,Math.PI*.62),accent,g,0,2.34,.08).scale.set(.99,1,.65)}else mesh(new THREE.CylinderGeometry(.32,.43,.18,8),mats.gold,g,0,2.52,0);for(let s of [-1,1]){let leg=mesh(new THREE.CylinderGeometry(.12,.15,.65,7),mats.armor,g,s*.19,.39,0);leg.rotation.z=s*.04;let arm=mesh(new THREE.CylinderGeometry(.1,.14,.82,7),coat,g,s*.41,1.56,0);arm.rotation.z=s*.27;}mesh(new THREE.BoxGeometry(.1,.88,.13),mats.silver,g,.47,1.38,.05).rotation.z=-.08;mesh(new THREE.BoxGeometry(.16,.3,.2),mats.gold,g,0,1.04,.34);return g}
const player=person({coat:mats.cloak,hood:true,accent:mats.red});player.position.set(0,0,5);scene.add(player);
function makeWolf(x,z,companion=false){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);const fur=companion?mats.wolf:mats.enemy;const torso=mesh(new THREE.SphereGeometry(.68,12,8),fur,g,0,.69,0);torso.scale.set(1.3,.72,.68);mesh(new THREE.SphereGeometry(.38,10,8),fur,g,0,1.05,.48);let ear1=mesh(new THREE.ConeGeometry(.14,.36,5),fur,g,-.2,1.42,.52),ear2=mesh(new THREE.ConeGeometry(.14,.36,5),fur,g,.2,1.42,.52);ear1.rotation.z=-.2;ear2.rotation.z=.2;for(let s of [-1,1]){mesh(new THREE.SphereGeometry(.055,8,6),companion?mats.gold:mats.fire,g,s*.15,1.1,.79);for(let k of [-1,1])mesh(new THREE.CylinderGeometry(.09,.1,.5,6),fur,g,s*.36,.32,k*.36)}const tail=mesh(new THREE.CylinderGeometry(.08,.14,.6,6),fur,g,0,.77,-.7);tail.rotation.x=-.8;g.userData={companion,hp:companion?100:38,maxHp:companion?100:38,dead:false,attackAt:0,speed:rand(.16,.28)};return g}
const companion=makeWolf(-2,7,true);const enemies=[];[[-12,8],[12,8],[-18,-9],[17,-15],[-7,-23],[26,1]].forEach(([x,z])=>enemies.push(makeWolf(x,z,false)));
// Maelis, a traveling merchant, and an armorer make the valley feel inhabited.
const npc=person({coat:new THREE.MeshStandardMaterial({color:0x73684e}),hood:false,accent:mats.gold});npc.position.set(-6,0,-2);npc.rotation.y=-.3;scene.add(npc);npc.userData={name:'Maelis',kind:'elder'};
const merchant=person({coat:new THREE.MeshStandardMaterial({color:0x566a55}),hood:false,accent:mats.gold});merchant.position.set(8,0,-8);merchant.rotation.y=2;scene.add(merchant);merchant.userData={name:'Tomas',kind:'merchant'};
const armorer=person({coat:new THREE.MeshStandardMaterial({color:0x4b5360}),hood:false,accent:mats.silver});armorer.position.set(-19,0,-13);armorer.userData={name:'Garrick',kind:'armorer'};
// Horse mount
function makeHorse(){const g=new THREE.Group();const brown=new THREE.MeshStandardMaterial({color:0x856044,roughness:.82});mesh(new THREE.BoxGeometry(.78,1.22,1.9),brown,g,0,1.3,0);const neck=mesh(new THREE.CylinderGeometry(.24,.38,1.25,8),brown,g,0,2.05,.7);neck.rotation.x=-.35;mesh(new THREE.SphereGeometry(.3,10,8),brown,g,0,2.65,1.08);mesh(new THREE.BoxGeometry(.85,.12,1.3),mats.red,g,0,1.94,-.1);for(let s of [-1,1])for(let z of [-.65,.65]){let l=mesh(new THREE.CylinderGeometry(.09,.12,1.1,7),brown,g,s*.24,.57,z);g.userData.legs=(g.userData.legs||[]).concat(l)}return g}
const horse=makeHorse();horse.visible=false;scene.add(horse);
const state={started:false,hp:100,maxHp:100,mana:60,maxMana:60,potions:3,level:3,xp:0,kills:0,questStage:0,questCount:0,mounted:false,attackReady:true,dialogueIndex:0,heroName:'ARIN VESPER',race:'Elfo',heroClass:'Patrulheiro',appearance:0,builds:0,paused:false};

const ui={health:document.querySelector('#healthBar'),healthText:document.querySelector('#healthText'),mana:document.querySelector('#manaBar'),manaText:document.querySelector('#manaText'),questTitle:document.querySelector('#questTitle'),questDesc:document.querySelector('#questDesc'),questProgress:document.querySelector('#questProgress'),questBar:document.querySelector('#questBar'),objective:document.querySelector('#objectiveText'),coords:document.querySelector('#coords'),prompt:document.querySelector('#interactionPrompt'),label:document.querySelector('#interactLabel'),toast:document.querySelector('#toast'),dialogue:document.querySelector('#dialogue')};
function refresh(){ui.health.style.width=`${state.hp/state.maxHp*100}%`;ui.healthText.textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;ui.mana.style.width=`${state.mana/state.maxMana*100}%`;ui.manaText.textContent=`${Math.ceil(state.mana)} / ${state.maxMana}`;document.querySelector('#level').textContent=String(state.level).padStart(2,'0');document.querySelector('#heroName').textContent=state.heroName;document.querySelector('#portraitInitial').textContent=state.heroName[0];document.querySelector('#raceClass').textContent=`${state.race.toUpperCase()} · ${state.heroClass.toUpperCase()}`;let q=state.questStage;if(q===0){ui.questTitle.textContent='Sombras na floresta';ui.questDesc.textContent='Fale com a anciã Maelis na clareira.';ui.questProgress.textContent='0 / 1';ui.questBar.style.width='0%';ui.objective.textContent='Clareira da anciã'}else if(q===1){ui.questTitle.textContent='Sombras na floresta';ui.questDesc.textContent='Derrote lobos corrompidos perto do acampamento.';ui.questProgress.textContent=`${state.questCount} / 3`;ui.questBar.style.width=`${state.questCount/3*100}%`;ui.objective.textContent='Lobos corrompidos'}else{ui.questTitle.textContent='Luz depois da sombra';ui.questDesc.textContent='Volte a Maelis para receber sua recompensa.';ui.questProgress.textContent='1 / 1';ui.questBar.style.width='100%';ui.objective.textContent='Fale com Maelis'}document.querySelector('[data-slot="2"] .slot-count').textContent=state.potions;}
let toastTimer;function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2300)}
function openModal(title,content,subtitle='REFÚGIO DA FRONTEIRA'){const modal=document.querySelector('#modalContent');modal.innerHTML=`<div class="modal-head"><div><small>${subtitle}</small><h2>${title}</h2></div><button class="close-modal" aria-label="Fechar">×</button></div>${content}`;document.querySelector('#modalBackdrop').classList.remove('hidden');modal.querySelector('.close-modal').onclick=closeModal;document.querySelector('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};}
function closeModal(){document.querySelector('#modalBackdrop').classList.add('hidden')}
const inventory=[['⚔','Lâmina lunar','1'],['◈','Poção vital',String(state.potions)],['✧','Cristal de éter','2'],['🌿','Erva-luz','5'],['⬡','Minério de ferro','4'],['🪶','Pena de grifo','1'],['♧','Carne assada','2'],['◆','Fragmento rúnico','3']];
function showPanel(kind){const title={inventory:'Mochila',character:'Seu personagem',quests:'Diário de missões',build:'Construir abrigo'}[kind];if(kind==='inventory'){openModal(title,`<div class="tab-row"><button class="tab-button selected">ITENS</button><button class="tab-button">EQUIPAMENTO</button><button class="tab-button">MATERIAIS</button><span style="margin-left:auto;color:#aaa38f;font-size:9px;align-self:center">${inventory.length} / 30</span></div><div class="inventory-grid">${inventory.map(a=>`<div class="item-card"><span class="item-icon">${a[0]}</span><small>${a[1]}</small><i>${a[2]}</i></div>`).join('')}</div>`)}else if(kind==='character'){openModal(title,`<div class="tab-row"><button class="tab-button selected">ATRIBUTOS</button><button class="tab-button">APARÊNCIA</button><button class="tab-button">CLASSE</button><button class="tab-button">RAÇA</button></div><div class="stats-grid"><div class="stat-box"><small>NÍVEL · EXPERIÊNCIA</small><b>${state.level} · ${state.xp} XP</b></div><div class="stat-box"><small>RAÇA · CLASSE</small><b style="font-size:15px">${state.race} · ${state.heroClass}</b></div><div class="stat-box"><small>VITALIDADE</small><b>♥ ${state.maxHp}</b></div><div class="stat-box"><small>ESSÊNCIA</small><b>✧ ${state.maxMana}</b></div><div class="stat-box"><small>FORÇA</small><b>${10+state.level*2}</b></div><div class="stat-box"><small>AGILIDADE</small><b>${14+state.level}</b></div></div><p style="font-size:9px;color:#aaa38f;margin:13px 0 0">Aventureiro da fronteira · Companheira: Lyra · ${state.kills} criaturas derrotadas</p><button class="action-button" id="customize">PERSONALIZAR PERSONAGEM</button> <button class="action-button" id="classChange">ESCOLHER CLASSE</button>`,`FICHA DO HERÓI`);document.querySelector('#customize').onclick=()=>customize();document.querySelector('#classChange').onclick=()=>chooseClass();}else if(kind==='quests'){openModal(title,`<div class="quest-list"><div class="quest-row"><span>✧</span><div><b>${state.questStage<2?'Sombras na floresta':'Sombras na floresta · CONCLUÍDA'}</b><small>${state.questStage===0?'Encontre Maelis na clareira.':state.questStage===1?`Derrote lobos corrompidos (${state.questCount}/3).`:'Uma sombra se ergueu, mas a floresta está segura.'}</small></div></div><div class="quest-row"><span>♧</span><div><b>Ervas para a jornada</b><small>Recolha 5 ervas-luz na floresta · 0/5</small></div></div><div class="quest-row"><span>⌂</span><div><b>Um lar na fronteira</b><small>Construa seu primeiro abrigo · ${state.builds?'1':'0'}/1</small></div></div><div class="quest-row"><span>♞</span><div><b>Montaria dos viajantes</b><small>Uma égua castanha espera junto ao acampamento.</small></div></div></div>`,`CAPÍTULO I · O VALE`)}else if(kind==='build'){const choices=[['⌂','Cabana','30 madeira'],['♨','Fogueira','12 madeira'],['▤','Baú','8 madeira'],['♧','Cerca','6 madeira'],['♜','Torre de vigia','20 madeira'],['⚒','Bancada','15 madeira']];openModal(title,`<p style="font-size:10px;color:#aaa38f">Erga seu refúgio na fronteira. Selecione uma estrutura para posicioná-la perto de você.</p><div class="build-grid">${choices.map((c,i)=>`<button class="build-card" data-build="${i}"><span>${c[0]}</span><b>${c[1]}</b><small>${c[2]}</small></button>`).join('')}</div><p style="font-size:9px;color:#c5b88e">Madeira disponível: 64 · Pedra: 28</p>`,`MODO CONSTRUÇÃO`);document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{placeBuild(Number(b.dataset.build));closeModal()})}}
function customize(){openModal('Personalize seu herói',`<p style="font-size:10px;color:#aaa38f">Escolha uma raça, um nome e um estilo para sua jornada.</p><label style="display:block;font-size:9px;color:#d0c59f;margin:12px 0 6px">NOME DO AVENTUREIRO</label><input id="nameInput" maxlength="18" value="${state.heroName}" style="width:100%;padding:10px;background:#ffffff0b;border:1px solid #ffffff24;color:#eee;font:12px Cinzel"><p style="font-size:9px;color:#d0c59f;margin-bottom:7px">RAÇA</p><div class="race-options">${[['Elfo','Ágil e atento às trilhas.'],['Humano','Versátil e resiliente.'],['Anão','Forte e mestre da forja.']].map(([n,d])=>`<button class="choice-card ${state.race===n?'selected':''}" data-race="${n}"><b>${n}</b><small>${d}</small></button>`).join('')}</div><p style="font-size:9px;color:#d0c59f;margin-bottom:7px">APARÊNCIA</p><div class="class-options"><button class="choice-card selected" data-look="0"><b>Capuz carmesim</b><small>O manto rubro da fronteira.</small></button><button class="choice-card" data-look="1"><b>Viajante élfico</b><small>Capa verde das florestas.</small></button><button class="choice-card" data-look="2"><b>Guardião solar</b><small>Manto dourado dos antigos.</small></button></div><button class="action-button" id="saveCustom">SALVAR PERSONAGEM</button>`,`ORIGEM E APARÊNCIA`);let picked=state.race,look=state.appearance;document.querySelectorAll('[data-race]').forEach(b=>b.onclick=()=>{picked=b.dataset.race;document.querySelectorAll('[data-race]').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelectorAll('[data-look]').forEach(b=>b.onclick=()=>{look=Number(b.dataset.look);document.querySelectorAll('[data-look]').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelector('#saveCustom').onclick=()=>{state.race=picked;state.appearance=look;state.heroName=(document.querySelector('#nameInput').value.trim()||'ARIN VESPER').toUpperCase();player.children[0].material=look===1?new THREE.MeshStandardMaterial({color:0x344c37}):look===2?new THREE.MeshStandardMaterial({color:0x80652f}):mats.cloak;refresh();closeModal();toast('PERSONAGEM ATUALIZADO')}}
function chooseClass(){openModal('Escolha seu caminho',`<p style="font-size:10px;color:#aaa38f">Sua classe define como você enfrenta os perigos de Eldoria.</p><div class="class-options">${[['Patrulheiro','⚔','Arco, lâminas e domínio da floresta.'],['Arcanista','✧','Essência arcana e feitiços poderosos.'],['Guardião','⬡','Armadura pesada e grande vitalidade.']].map(([n,i,d])=>`<button class="choice-card ${state.heroClass===n?'selected':''}" data-class="${n}"><b>${i} &nbsp; ${n}</b><small>${d}</small></button>`).join('')}</div><button class="action-button" id="saveClass">CONFIRMAR CLASSE</button>`,`ESCOLHA DE CLASSE`);let picked=state.heroClass;document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{picked=b.dataset.class;document.querySelectorAll('[data-class]').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelector('#saveClass').onclick=()=>{state.heroClass=picked;refresh();closeModal();toast(`CLASSE ALTERADA: ${picked.toUpperCase()}`)}}
function placeBuild(kind){const specs=[['Cabana',9,0x776b53],['Fogueira',2,0xd66e39],['Baú',1.2,0x735230],['Cerca',4,0x745a3d],['Torre',6,0x77705e],['Bancada',2,0x735c3a]];const [name,size,color]=specs[kind];let x=clamp(state.x+rand(-7,7),-35,35),z=clamp(player.position.z-7,-39,31);let material=new THREE.MeshStandardMaterial({color,roughness:.9});if(kind===0){let obj=new THREE.Group();obj.position.set(x,0,z);scene.add(obj);mesh(new THREE.BoxGeometry(5,3.2,5),material,obj,0,1.6,0);mesh(new THREE.ConeGeometry(4,2.4,4),mats.red,obj,0,4.4,0).rotation.y=Math.PI/4}else if(kind===1){let f=mesh(new THREE.IcosahedronGeometry(.55,1),mats.fire,scene,x,.5,z);new THREE.PointLight(0xff873a,1.5,8).position.set(x,1,z)}else if(kind===3){for(let i=-1;i<=1;i++)mesh(new THREE.BoxGeometry(3,.15,.15),material,scene,x+i*1.1,.65,z);for(let i=-1;i<=1;i++)mesh(new THREE.BoxGeometry(.14,1.3,.14),material,scene,x+i*1.1,.7,z)}else{mesh(new THREE.BoxGeometry(size,kind===4?size*1.7:1.3,size),material,scene,x,kind===4?size*.85:.65,z)}state.builds++;toast(`${name.toUpperCase()} CONSTRUÍDA`);}
